clearclcclose all% reading and converting to vectors the training facesa1 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil1.jpg'));imshow(uint8(a1));b1=a1(:);a2 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil2.jpg'));b2 = a2(:);a3 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil3.jpg'));b3 = a3(:);a4 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil4.jpg'));b4 = a4(:);a5 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil5.jpg'));b5 = a5(:);a6 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil6.jpg'));b6 = a6(:);a7 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil7.jpg'));b7 = a7(:);a8 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil8.jpg'));b8 = a8(:);a9 = double(imread('/Users/ab/Dropbox/curs-M2/PCA/pixil9.jpg'));b9 = a9(:);# plot all training faces in a single figureblank = 255*ones(5,3);blankline = [blank,blank,blank,blank,blank];a = [a1,blank,a2,blank,a3;blankline;a4,blank,a5,blank,a6;blankline;a7,blank,a8,blank,a9];buffer = sprintf('Imaginile de antrenare');figure(1,"position",get(0,"screensize")/4);imshow(uint8(a));title(buffer);# training matrix -- the 9-column vectors b1-b9 with 15 componentsdata = [b1,b2,b3,b4,b5,b6,b7,b8,b9];# mean of the training set mu = (1/9)*(b1+...+b9)mu = mean(data');# centralize training set b1-mu, ..., b9-mustddata = (data' - mu)';# plot mean image## convert from vector to matrixmuimg = reshape(mu,5,3); figure(2,"position",20+get(0,"screensize")/4);buffer = sprintf('Media imaginilor');imshow(uint8(muimg));title(buffer);pause(1)# covariance matrixcov_matrix = stddata*stddata'/8;# eigenvectors and eigenvalues of the covariance matrix[v,l] = eig(cov_matrix);# sort eigenvectors and eigenvalues [ll,perm] = sort(diag(l),'descend');vv=v(:,perm);# retain only the first two principal componentsbuffer = sprintf('Componentele principale');lambda1 = ll(1);lambda2 = ll(2);# eigenfaces spacevect1 = (vv'(1,:))';vect2 = (vv'(2,:))';U=[vect1,vect2];# test new image matrixt = [0,0,0;0,255,0;0,255,0;0,255,0;0,0,0];figure(3,"position",40+get(0,"screensize")/4);imshow(uint8(t));buffer = sprintf('Imaginea test');title(buffer);pause(1)# convert new test image matrix to vectortt = t(:);# project test image on the space of eigenfacespr_tt = [vect1'*(tt-mu');vect2'*(tt-mu')];# plot the projection of the new test image on the space of eigenfaces, together with (the projections of the) training dataxU=(U'*stddata)(1,:);yU=(U'*stddata)(2,:);figure(4,"position",get(0,"screensize"));plot(xU,yU,'rx',pr_tt(1,:),pr_tt(2,:),'+b');labels = cellstr( num2str([1:9]') );text(xU, yU, labels, 'VerticalAlignment','bottom', 'HorizontalAlignment','right');text(pr_tt(1,:),pr_tt(2,:), num2str(0),'VerticalAlignment','bottom', 'HorizontalAlignment','right');buffer = sprintf('Proiectia noii imagini pe spatiul redus al imaginilor de antrenare');title(buffer);pause(1)